function inspectionCoverage(){return `<div class="inspection-coverage"><strong>${t('正常查验费用已含','Standard customs inspection costs included')}</strong><p>${t('查验产生的费用由渠道承担，不向客户另行收取。','The channel provider covers all customs inspection-related costs. No additional charge to you.')}</p><small>${t('查验可能影响交期；如遇查验，我们会同步进度并更新预计到仓日期。','Inspections may affect delivery timing. We will share progress and update the estimated warehouse arrival date.')}</small></div>`}
const $=s=>document.querySelector(s),E=QuoteEngine;let en=false,step=1,tab='quote',kind='',sort='price',plans=[];const today=new Date().toISOString().slice(0,10);let base={product:'',weight:'',volume:'',cartons:'',pieces:'',destination:'',zip:'',origin:'Shanghai',ready:today,deadline:''},trade={fobUnit:'',load:'AUTO',delivery:'transload',containers:'1',hts:'',country:'China',tax:'',fees:'',tariff:null,entryDate:'',entries:'1',taxTreatment:'standard',broker:'ours',brokerFee:'150'};let saved=[],legacy=[];try{saved=JSON.parse(localStorage.getItem('apparel-quotes-v2')||'[]');legacy=JSON.parse(localStorage.getItem('apparel-quotes-v1')||'[]');if(!Array.isArray(saved))saved=[];if(!Array.isArray(legacy))legacy=[]}catch{}const t=(a,b)=>en?b:a,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);function msg(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}function go(s){step=s;render();window.scrollTo({top:0,behavior:'smooth'})}function field(key,label,value,type='text',unit='',extra='',wide=false){return `<label class="field ${wide?'wide':''}"><span>${label}</span><div><input name="${key}" type="${type}" value="${esc(value)}" ${extra}>${unit?`<em>${unit}</em>`:''}</div></label>`}function select(key,label,value,items){return `<label class="field"><span>${label}</span><select name="${key}">${items.map(([v,n])=>`<option value="${v}" ${v===value?'selected':''}>${n}</option>`).join('')}</select></label>`}const origins=()=>[['Shanghai',t('上海','Shanghai')],['Ningbo',t('宁波','Ningbo')],['Shenzhen',t('深圳','Shenzhen')],['Qingdao',t('青岛','Qingdao')],['Xiamen',t('厦门','Xiamen')]];function capture(){const f=$('#basic-form'),g=$('#trade-form');if(f)base={...base,...Object.fromEntries(new FormData(f))};if(g)trade={...trade,...Object.fromEntries(new FormData(g))}}const destinationOptions=()=>[['fba','FBA'],['awd','AWD'],['commercial',t('商业仓库','Commercial warehouse')],['other',t('其他地址','Other address')]];function destinationLabel(value){return destinationOptions().find(x=>x[0]===value)?.[1]||t('目的地类型待补充','Destination type not specified')}function destinationField(){return `<fieldset class="destination-field"><legend>${t('目的地类型','Destination type')}</legend><div class="destination-options">${destinationOptions().map(([value,label])=>`<label><input type="radio" name="destination" value="${value}" ${base.destination===value?'checked':''} required><span>${label}</span></label>`).join('')}</div></fieldset>`}function summary(){return `<div class="shipment"><div><b>${esc(base.product)}</b><p>${esc(base.origin)} → US ${esc(base.zip)} · ${destinationLabel(base.destination)} · ${esc(base.weight)} KG · ${esc(base.volume)} CBM</p><p>${esc(base.cartons)} CTNS / ${esc(base.pieces)} PCS · ${t('货好','Ready')} ${base.ready}</p></div><button class="link" data-go="1">${t('修改资料','Edit')}</button></div>`}function intro(k,title,sub=''){return `<p class="eyebrow">${k}</p><h1>${title}</h1>${sub?`<p class="sub">${sub}</p>`:''}`}function warning(){return `<p class="notice">${t('演示版：价格、渠道覆盖和全程时效均为示例，未连接承运人实时运价、船期或海关税则。','Demo: rates, coverage and transit times are illustrative. Live carrier rates, schedules and customs data are not connected.')}</p>`}function render(){document.documentElement.lang=en?'en':'zh-CN';$('#header').innerHTML=`<a class="brand" href="./"><b>Q</b><span>${t('运费助手','Freight Assistant')}<small>SWIFTWIDE</small></span></a><div class="headright"><span class="demo">${t('交互演示','Interactive demo')}</span><div class="lang"><button data-lang="zh" class="${!en?'active':''}">中文</button><button data-lang="en" class="${en?'active':''}">English</button></div></div>`;$('#nav').innerHTML=['quote','saved','orders'].map((x,i)=>`<button data-tab="${x}" class="${tab===x?'active':''}"><span>${['⊞','▤','▱'][i]}</span><i>${[t('快速报价','Quick quote'),t('我的报价','My quotes'),t('我的订单','My orders')][i]}</i></button>`).join('');let h='';if(tab==='saved'){h=intro('QUOTES',t('我的报价','My quotes'),t('仅保存在当前浏览器，不跨设备同步。','Saved in this browser only; no cross-device sync.'))+`<div class="saved-grid">`+saved.map(q=>`<article class="card"><span class="pill">${t('演示报价','Demo quote')} · ${q.kind==='ecom'?t('电商','E-commerce'):t('传统','Traditional')}</span><h2>${esc(q.base.product)}</h2><p class="route-summary">US ${esc(q.base.zip)} · ${destinationLabel(q.base.destination)} · ${esc(q.plan[en?'en':'zh'])}</p><p class="note">${q.kind==='ecom'?t('不含货值 · 税费范围待确认','Excludes goods · duty coverage unconfirmed'):q.plan.complete?t('含 FOB 及手动税费','Includes FOB and manual customs costs'):t('含 FOB · 税费未计全','Includes FOB · customs incomplete')}</p><div class="saved-unit"><span>${t('每件费用','Cost / piece')}</span><strong>${usd(q.plan.per)}</strong><small>USD / PCS</small></div><p>${q.plan.min}–${q.plan.max} ${t('天 · 预计到仓','days to warehouse')}</p><button class="secondary" data-reopen="${q.id}">${t('重新查看方案','Reopen comparison')}</button></article>`).join('')+legacy.map(q=>`<article class="card"><span class="pill">${t('历史演示报价','Earlier demo quote')}</span><h2>${esc(q.data?.product)}</h2><p>${esc(q.plan?.name?.[en?1:0])}</p><div class="price">${usd(q.plan?.total||0)}</div><p class="note">${t('旧版记录已保留，不适用新版计费规则。','Preserved from the previous version; not recalculated.')}</p></article>`).join('')+(!saved.length&&!legacy.length?`<div class="empty"><h2>${t('还没有保存的报价','No saved quotes yet')}</h2><p>${t('比较运输方案后，可保存感兴趣的报价。','Save a shipping option after comparing quotes.')}</p></div>`:'')+'</div>'}else if(tab==='orders'){h=intro('ORDERS',t('我的订单','My orders'))+`<div class="empty"><h2>${t('暂无运输订单','No shipments yet')}</h2><p>${t('当前版本用于报价演示，尚未接入订舱和物流跟踪。','This demo does not book or track shipments.')}</p><button class="secondary" data-tab="quote">${t('去报价','Get a quote')}</button></div>`}else{h=`<div class="steps">${[t('货物资料','Shipment'),t('物流类型','Service type'),t('价格与时效','Price & transit')].map((s,i)=>`<div class="${(step===1?0:step===2?1:2)===i?'on':''}"><b>${i+1}</b><span>${s}</span></div>`).join('')}</div>`;if(step===1)h+=basicPage();if(step===2)h+=choicePage();if(step===3)h+=tradePage();if(step===4)h+=resultPage()}$('#app').innerHTML=h;bind()}
function basicPage(){return intro(t('快速估算 · 输入货物资料','QUICK ESTIMATE · SHIPMENT DETAILS'),t('服装出口美国运费查询','U.S. apparel freight quotes'),t('填写一次货物资料，再选择电商或传统物流。','Enter shipment details, then choose e-commerce or traditional freight.'))+`<div class="entry-grid"><form id="basic-form"><div class="fields">${field('product',t('详细品名','Product description'),base.product,'text','','required maxlength="100" placeholder="'+t('例如：女式棉制针织上衣',"Women's cotton knit tops")+'"',true)}${field('weight',t('总毛重','Gross weight'),base.weight,'number','KG','required min="0.1" max="1000000" step="0.1" placeholder="480"')}${field('volume',t('总体积','Volume'),base.volume,'number','CBM','required min="0.01" max="10000" step="0.01" placeholder="26.5"')}${field('cartons',t('总箱数','Cartons'),base.cartons,'number','CTNS','required min="1" max="1000000" step="1" placeholder="100"')}${field('pieces',t('服装数量','Garment quantity'),base.pieces,'number','PCS','required min="1" max="100000000" step="1" placeholder="1200"')}${select('origin',t('中国起运地','Origin in China'),base.origin,origins())}${destinationField()}${field('zip',t('目的地仓库 ZIP Code','Warehouse ZIP Code'),base.zip,'text','','required inputmode="numeric" pattern="[0-9]{5}" maxlength="5" placeholder="91748"')}${field('ready',t('预计货好日期','Cargo ready date'),base.ready,'date','','required')}${field('deadline',t('希望最晚到仓（选填）','Delivery deadline (optional)'),base.deadline,'date')}</div><p class="note">${t('请填写最终收货仓库的邮编，用于匹配尾程配送。','Use the final receiving warehouse ZIP for delivery pricing.')}</p><button class="primary" type="submit">${t('下一步','Next')} <span>→</span></button><button class="textbutton" id="sample" type="button">${t('填入示例，体验报价','Try a sample shipment')}</button></form></div>`}
function choicePage(){return intro(t('第二步 · 选择物流类型','STEP 2 · CHOOSE FREIGHT TYPE'),t('请选择物流类型','Select freight type'),t('两种计费方式，各自独立核算。','Two freight types, with separate pricing rules.'))+summary()+`<div class="choices"><button class="choice" data-kind="ecom"><span class="choice-code">01 / E-COMMERCE</span><h2>${t('电商物流','E-commerce freight')}</h2><p>${t('比较不同方案的到仓费用和时效。','Compare delivery costs and transit times across services.')}</p><div class="tags"><span>${t('普船','Regular')}</span><span>${t('普快','Expedited')}</span><span>${t('美森','Matson')}</span></div>${inspectionCoverage()}<p class="note">${t('东岸可比较直航纽约及海运转卡方案。','East Coast options include direct New York and ocean + truck.')}</p><strong class="choice-action">${t('查看电商方案','See e-commerce options')} →</strong></button><button class="choice" data-kind="trade"><span class="choice-code">02 / TRADITIONAL TRADE</span><h2>${t('传统物流','Traditional freight')}</h2><p>${t('拼箱或整柜，分项核算到仓成本。','LCL or FCL, with itemized landed costs.')}</p><div class="tags"><span>LCL</span><span>FCL</span><span>${t('独立清关','Own importer')}</span></div><p class="note">${t('补充 FOB 货值、装载方式与清关费用。','Add FOB value, load type and customs costs.')}</p><strong class="choice-action">${t('补充传统贸易资料','Add trade details')} →</strong></button></div><button class="textbutton" data-go="1">← ${t('返回修改货物资料','Back to shipment details')}</button>`}
function deliveryFields(){const lp=E.loadPlan(base,trade);return `<p class="note">${lp.load==='LCL'?t('海运按拼箱报价。','Ocean freight priced as LCL.'):t('海运参考方案：','Ocean reference: ')+lp.load+' × '+lp.containers+' · '+t('柜量及装载条件待确认','Container count and loading subject to confirmation')}</p>${lp.load!=='LCL'?select('delivery',t('美国送仓方式','U.S. delivery'),trade.delivery||'transload',[['transload',t('拆柜后卡车派送','Transload, then truck delivery')],['direct',t('整柜直接送仓','Direct container delivery')]]):''}<p class="notice">${lp.delivery==='direct'?t('按整柜拖柜报价，不另加托盘派送费。','Priced as container drayage; no pallet delivery charge.'):lp.large?t('大货按整车派送估算，车数及装载条件需仓库确认。','Large shipments use truckload estimates. Warehouse confirmation of truck count and loading is required.'):t('按每托约 2 CBM 估算：','Estimate at 2 CBM per pallet: ')+base.volume+' ÷ '+FreightRules.cbmPerPallet+' → '+lp.pallets+' '+t('托。实际托盘资料由仓库提供。','pallets. Actual pallet data is supplied by the warehouse.')}</p>`}function deliveryBreakdown(p){if(!p.deliveryQuote)return '';const q=p.deliveryQuote;return `<div class="delivery-estimate"><b>${q.mode==='pallet'?t('尾程按托报价','Pallet delivery'):q.mode==='ftl'?t('尾程整车报价','Truckload delivery'):t('整柜直送报价','Container drayage')}</b><p>${q.mode==='pallet'?esc(base.volume)+' CBM ÷ '+FreightRules.cbmPerPallet+' → '+q.units+' '+t('托','pallets'):q.units+' '+(q.mode==='ftl'?t('车（预估）','truck(s), estimated'):t('柜（预估）','container(s), estimated'))} × ${usd(q.unitRate)} = <strong>${usd(q.total)}</strong></p><span>${t('演示单价。最终托数、车数、重量及收货仓要求需确认。','Demo rate. Final counts, weight and warehouse requirements need confirmation.')}</span></div>`}
function taxInputs(){return `<div class="fields">${field('entryDate',t('预计进口日期','Estimated entry date'),trade.entryDate||E.arrival(base.ready,35),'date','','required')}${select('taxTreatment',t('进口方式','Import treatment'),trade.taxTreatment||'standard',[['standard',t('普通海运正式报关','Ordinary formal ocean entry')],['review',t('有豁免或特殊情况','Exemption / special case')]])}</div><p class="note">${t('按一票报关、FOB 货值作为计税基础估算。特殊归类、豁免、反倾销或反补贴等情况需复核。','Assumes one customs entry and FOB as customs value. Special classifications, exclusions and AD/CVD require review.')}</p>`}
let tariffMatches=[],tariffQuery='',tariffData=null;function tariffPanel(){const r=trade.tariff;return `<section class="tariff-panel"><h2>${t('商品归类','Product classification')}</h2><p class="note">${t('输入 HTS 编码或英文品名，自动匹配商品。选定后自动计算税费，无需填写税率。','Enter an HTS code or English product name. Select the matching item; duties are calculated automatically.')}</p><div class="tariff-search"><input id="tariff-query" aria-label="HTS or product" value="${esc(tariffQuery)}" placeholder="6109.10 / cotton T-shirts"></div><div id="tariff-matches" aria-live="polite"></div>${r?`<div class="selected-tariff"><b>${esc(r.code)} · ${t('一般税率','General rate')} ${esc(r.rate||t('待确认','Unconfirmed'))}</b><p>${esc(r.description)}</p><p>${t('税费按 FOB 总货值估算，并自动分摊至每件服装。','Duties and fees are estimated on FOB value and allocated per garment.')}</p><button type="button" class="link" id="clear-tariff">${t('重新选择编码','Clear selection')}</button></div>`:''}<p class="notice">${t('普通中国原产服装：自动核算基础关税、已匹配附加税及 MPF/HMF。豁免、未匹配编码或复合税率显示待确认，不按零费用处理。','Ordinary China-origin apparel: base duty, matched additional duties and MPF/HMF are calculated. Exclusions, unmatched codes and compound rates remain unconfirmed, not zero.')}</p><p class="note"><a href="https://hts.usitc.gov/" target="_blank" rel="noopener">USITC HTSUS</a> · 2026 Revision 19 · ${t('数据下载日期：2026-09-19。当前为固定版本，未自动更新；进口前需核对适用版本、章注及原产地规则。','Snapshot downloaded 2026-09-19; not auto-updated. Verify the applicable edition, chapter notes and origin rules before import.')}</p></section>`}function bindTariffs(){const input=$('#tariff-query');if(!input)return;let seq=0;const lookup=async()=>{capture();const box=$('#tariff-matches'),query=$('#tariff-query').value.trim();if(!query){box.textContent=t('请输入编码或英文品名。','Enter an HTS code or English keywords.');return}const ticket=++seq;box.textContent=t('正在读取官方税则…','Loading official tariff data…');try{tariffData=await Tariffs.load();if(ticket!==seq||!box.isConnected)return;const found=Tariffs.search(tariffData,query);tariffMatches=found.slice(0,30);box.innerHTML=found.length?`<p class="note">${t('找到','Found')} ${found.length} ${t('项','entries')}${found.length>30?t('，显示前 30 项，请补充关键词缩小范围。',', showing first 30; refine your search.'):''}</p>`+tariffMatches.map((r,i)=>`<button type="button" class="tariff-result" data-tariff="${i}"><strong>${esc(r.code)} <span>${esc(r.rate||t('待确认','Unconfirmed'))}</span></strong><p>${esc(r.description)}</p><small>${t('选择此编码','Select code')} →</small></button>`).join(''):t('没有匹配结果，请用 HTS 编码或英文关键词查询。','No matches. Try an HTS code or English keywords.');box.querySelectorAll('[data-tariff]').forEach(b=>b.onclick=()=>{capture();trade.tariff={...tariffMatches[Number(b.dataset.tariff)],version:tariffData.version,retrieved:tariffData.retrieved};trade.hts=trade.tariff.code;trade.tax='';trade.fees='';render()})}catch{box.textContent=t('税则数据加载失败，请重试。','Could not load tariff data. Please retry.')}};input.oninput=e=>{tariffQuery=e.target.value;seq++;clearTimeout(window.tariffTimer);window.tariffTimer=setTimeout(lookup,400)};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(window.tariffTimer);lookup()}};if($('#clear-tariff'))$('#clear-tariff').onclick=()=>{capture();trade.tariff=null;trade.hts='';render()}}
function fobSummary(){const unit=Number(trade.fobUnit),count=Number(base.pieces);return `<span>${t('FOB 总货值（自动计算）','Total FOB value (calculated)')}</span><b>${unit>0&&Number.isFinite(unit)?usd(Math.round(unit*count*100)/100):'—'}</b><p>${unit>0&&Number.isFinite(unit)?esc(trade.fobUnit):'—'} USD / PCS × ${count.toLocaleString()} ${t('件','pieces')}</p>`}
function tradePage(){return intro(t('传统物流 · 补充贸易资料','TRADITIONAL FREIGHT · TRADE DETAILS'),t('传统物流报价','Traditional freight quote'),t('FOB 货值与清关费用分开填写。','FOB cargo value and customs service fees are separate.'))+summary()+`<form id="trade-form"><div class="trade-panel"><h2>${t('货值与装载方式','Value & load type')}</h2><div class="fields">${field('fobUnit',t('FOB 单价','FOB unit price'),trade.fobUnit,'number','USD / PCS','required min="0.0001" max="1000000" step="0.0001" placeholder="15.00"')}${select('load',t('装载方式','Load type'),trade.load,[['AUTO',t('按货量匹配','Match by volume')],['LCL',t('拼箱 LCL · 按 CBM','LCL · per CBM')],['20GP','FCL 20GP'],['40GP','FCL 40GP'],['40HQ','FCL 40HQ'],['45HQ','FCL 45HQ']])}${!['LCL','AUTO'].includes(trade.load)?field('containers',t('柜量','Container quantity'),trade.containers,'number',t('柜','units'),'required min="1" max="100" step="1"'):''}</div><div id="fob-total" class="fob-total" aria-live="polite">${fobSummary()}</div>${deliveryFields()}<h2>${t('清关及税费','Customs & duties')}</h2><div class="fields">${field('country',t('原产国','Country of origin'),trade.country,'text','','required maxlength="60"')}${select('broker',t('报关安排','Customs brokerage'),trade.broker,[['ours',t('由我们安排','Arrange through us')],['own',t('客户自己的报关行','Customer’s own broker')]])}${trade.broker==='own'?field('brokerFee',t('报关行报价（客户自付）','Broker fee (paid by customer)'),trade.brokerFee,'number','USD','required min="0" max="1000000" step="0.01"'):''}</div>${taxInputs()}${tariffPanel()}</div><button class="primary" type="submit">${t('查询报价','Get quotes')} →</button><button class="textbutton" type="button" data-go="2">← ${t('返回选择物流类型','Back to freight type')}</button></form>`}
function tariffResultNote(){return `<div class="notice">${trade.tariff?esc(trade.tariff.code)+' · '+esc(trade.tariff.version):t('商品编码待确认','Product code unconfirmed')}<br>${t('按 2026-09-19 税则快照估算；未来政策变化、特殊税项及申报条件需复核。MPF 按预计进口日期匹配财年。','Estimated using the 2026-09-19 snapshot. Future changes, special duties and entry conditions need review. MPF fiscal year follows the estimated entry date.')}</div>`}function taxCostBlock(p){const x=p.taxSummary;if(!x)return '';return `<section class="tax-cost"><div><span>${x.complete?t('每件税费估算','Estimated duties & fees / piece'):t('每件已知税费 · 未计全','Known duties & fees / piece · incomplete')}</span><strong>${usd(x.per)}<small> USD / PCS</small></strong></div><p>${t('整票税费','Shipment duties & fees')}${x.complete?'':t('（已知部分）',' (known portion)')}：${usd(x.total)}</p><details><summary>${t('税费明细','Duty & fee breakdown')}</summary>${x.rows.map(r=>`<div class="breakdown"><span>${esc(r[en?1:0])}<small>${r[2]===null?'':esc(r[3])}</small></span><b>${r[2]===null?t('待确认','Unconfirmed'):usd(r[2])}</b></div>`).join('')}<p class="note">${t('仅含政府税费，不含报关服务费和运费；按一票普通海运正式报关估算。','Government duties and fees only; excludes brokerage and freight. Assumes one ordinary formal ocean entry.')}</p><p class="note"><a href="https://hts.usitc.gov/" target="_blank" rel="noopener">HTSUS</a> · <a href="https://www.ecfr.gov/current/title-19/chapter-I/part-24/section-24.23" target="_blank" rel="noopener">MPF</a> · <a href="https://www.ecfr.gov/current/title-19/chapter-I/part-24/section-24.24" target="_blank" rel="noopener">HMF</a> · <a href="https://www.federalregister.gov/documents/2026/07/31/2026-15530/customs-user-fees-to-be-adjusted-for-inflation-in-fiscal-year-2027" target="_blank" rel="noopener">MPF FY2027</a></p></details></section>`}
function resultPage(){const ordered=[...plans].sort((a,b)=>sort==='price'?a.total-b.total:a.max-b.max);return intro(kind==='ecom'?t('电商物流 · 渠道比价','E-COMMERCE · CHANNEL COMPARISON'):t('传统物流 · 到仓成本','TRADITIONAL · LANDED COST'),t('报价结果','Quote results'),t('从货好日期起算，展示到最终仓库的预计时间。','Estimated warehouse arrival, measured from the cargo-ready date.'))+summary()+`<div class="result-controls"><span>${kind==='ecom'?t('按渠道公斤价 · 含尾程演示','Per-kg channels · demo includes delivery'):(plans[0]?.loadPlan?.load==='LCL'?t('拼箱 · 按体积计费','LCL · billed by volume'):(plans[0]?.loadPlan?.load||trade.load)+' × '+(plans[0]?.loadPlan?.containers||trade.containers))}</span><label>${t('排序','Sort')} <select id="sort"><option value="price" ${sort==='price'?'selected':''}>${t('价格优先','Lowest price')}</option><option value="time" ${sort==='time'?'selected':''}>${t('时效优先','Fastest arrival')}</option></select></label></div>${warning()}<div class="results-grid">`+ordered.map(p=>{const earliest=E.arrival(base.ready,p.min),latest=E.arrival(base.ready,p.max),status=!base.deadline?'':latest<=base.deadline?t('预计满足交期','Estimated within deadline'):earliest>base.deadline?t('预计晚于交期','Estimated after deadline'):t('交期存在风险','Deadline at risk');return `<article class="card ${p===ordered[0]?'featured':''}"><div class="card-head"><h2>${esc(p[en?'en':'zh'])}</h2><span class="pill">${p===ordered[0]?(sort==='price'?t('价格最低','Lowest price'):t('预计最快','Fastest')):t('演示方案','Demo')}</span></div><div class="quote-key"><div class="unit-main"><span>${kind==='ecom'?t('每件到仓运费','Delivery cost / piece'):p.complete?t('每件 DDP 成本估算','DDP estimate / piece'):t('每件已知到仓成本','Known landed cost / piece')}</span><div><strong>${usd(p.per)}</strong><small>USD / PCS</small></div><p>${kind==='ecom'?t('不含货值 · DDP 税费范围待确认','Excludes goods · DDP duty coverage unconfirmed'):p.complete?t('含 FOB 货值及税费估算','Includes FOB value and estimated duties and fees'):t('含 FOB 货值 · 税费未计全','Includes FOB · customs costs incomplete')}</p></div><div class="transit-main"><span>${t('预计全程时效','Estimated transit')}</span><div><strong>${p.min}–${p.max}</strong><small>${t('天','days')}</small></div><p>${t('从货好日期起算','From cargo-ready date')}</p></div></div>${kind==='ecom'?inspectionCoverage():''}${taxCostBlock(p)}<div class="arrival-line"><span>${t('预计到仓','Estimated arrival')}</span><strong>${earliest} — ${latest}</strong></div>${status?`<p class="deadline-status">${status} · ${base.deadline}</p>`:''}<div class="order-total"><span>${kind==='ecom'?t('订单运费','Order freight'):p.complete?t('订单到仓成本（含 FOB）','Order landed cost (incl. FOB)'):t('订单已知成本（含 FOB）','Known order costs (incl. FOB)')}</span><b>${usd(kind==='ecom'?p.total:p.landed)}</b></div><p class="quantity-note">${Number(base.pieces).toLocaleString()} ${t('件 · 单件金额显示至美分，总价按未舍入金额计算','pieces · Unit prices rounded to cents; totals use unrounded values')}</p><details><summary>${t('费用明细与时效说明','Cost details & transit notes')}</summary>${kind==='trade'?tariffResultNote():''}${deliveryBreakdown(p)}${kind==='trade'?`<div class="breakdown"><span>${t('FOB 总货值','Total FOB value')} · ${esc(trade.fobUnit)} × ${Number(base.pieces).toLocaleString()} PCS</span><b>${usd(p.fobTotal)}</b></div>`:''}${kind==='ecom'?`<p class="note">${usd(p.rate)} / KG · ${t('计费重','Billed weight')} ${p.billed} KG</p>`:`<div class="breakdown"><span>${t('物流及进口费用小计（不含货值）','Logistics & import subtotal (excl. goods)')}</span><b>${usd(p.total)}</b></div>`}${p.rows.map(r=>`<div class="breakdown"><span>${r[en?1:0]}</span><b>${r[2]===null?t('待确认','Unconfirmed'):usd(r[2])}</b></div>`).join('')}<p class="note">${kind==='ecom'?t('示例规则：计费重取毛重与 CBM × 167 较大值，向上取整。渠道价已含尾程；税费包含范围待供应商确认。','Demo billed weight: ceil(max(gross kg, CBM × 167)). Delivery included; duty coverage requires supplier confirmation.'):p.loadPlan?.load==='LCL'?t('示例海运价：','Demo ocean rate: ')+usd(p.oceanRate)+'/CBM · '+t('最低 1 CBM。重货及特殊货物需复核。','1 CBM minimum. Heavy or special cargo needs review.'):t('示例按柜计费；柜量由客户填写，未验证装载容量。','Demo per-container pricing; supplied container count is not capacity-validated.')}</p><p class="note">${kind==='ecom'?t('时效为预计时间，包含集货等船、海运、清关提货及送仓。查验产生的费用由渠道承担，不向客户另行收取。如遇查验，我们会同步进度并更新预计到仓日期。当前展示为示例时效，未匹配真实船期或仓库预约；保险及其他特殊服务另计。','Transit times are estimates covering consolidation, ocean transport, customs release and warehouse delivery. The channel provider covers all customs inspection-related costs, with no additional charge to the customer. If an inspection occurs, we will share progress and update the estimated warehouse arrival date. Displayed transit times are illustrative, with no live sailing or appointment matching; insurance and other special services are charged separately.'):t('时效包含示例集货等船、海运、清关提货及送仓时间；未匹配真实船期或仓库预约，不构成到货保证。查验、保险及特殊服务另计。','Illustrative transit includes consolidation, ocean, customs release and delivery. No live sailing or appointment matching; arrival is not guaranteed. Inspection, insurance and special services excluded.')}</p></details><button class="secondary" data-save="${p.id}">${t('保存报价','Save quote')}</button></article>`}).join('')+`</div><button class="textbutton" data-go="${kind==='trade'?3:2}">← ${t('返回调整报价','Back to adjust quote')}</button>`}
function compute(){plans=kind==='ecom'?E.ecommerce(base):E.traditional(base,trade)}function bind(){bindTariffs();document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{capture();en=b.dataset.lang==='en';render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{capture();tab=b.dataset.tab;render();window.scrollTo({top:0})});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{capture();go(+b.dataset.go)});if($('#basic-form'))$('#basic-form').onsubmit=e=>{e.preventDefault();capture();try{E.valid(base);go(2)}catch{msg(t('请检查货物资料，最晚到仓日期不能早于货好日期。','Check shipment details and delivery deadline.'))}};if($('#sample'))$('#sample').onclick=()=>{base={product:t('女式棉制针织上衣',"Women's cotton knit tops"),weight:'480',volume:'26.5',cartons:'100',pieces:'1200',zip:'08817',destination:'fba',origin:'Shanghai',ready:today,deadline:E.arrival(today,40)};render()};document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;if(kind==='ecom'){compute();go(4)}else go(3)});if($('#trade-form')){$('#trade-form').elements.country.onchange=()=>{capture();trade.tariff=null;render()};$('#trade-form').elements.fobUnit.oninput=e=>{trade.fobUnit=e.target.value;$('#fob-total').innerHTML=fobSummary()};for(const key of ['load','broker','delivery','taxTreatment'])if($('#trade-form').elements[key])$('#trade-form').elements[key].onchange=()=>{capture();render()};$('#trade-form').onsubmit=e=>{e.preventDefault();capture();try{compute();go(4)}catch{msg(t('请检查货值和清关费用。','Check cargo value and customs fees.'))}}}if($('#sort'))$('#sort').onchange=e=>{sort=e.target.value;render()};document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const plan=plans.find(p=>p.id===b.dataset.save),q={id:crypto.randomUUID(),base:{...base},trade:{...trade},kind,plan,date:new Date().toISOString()};try{localStorage.setItem('apparel-quotes-v2',JSON.stringify([q,...saved]));saved.unshift(q);msg(t('已保存到当前浏览器','Saved in this browser'))}catch{msg(t('无法保存，请检查浏览器存储设置','Browser storage unavailable'))}});document.querySelectorAll('[data-reopen]').forEach(b=>b.onclick=()=>{const q=saved.find(x=>x.id===b.dataset.reopen);base={...q.base,destination:q.base.destination||''};trade={delivery:'transload',entryDate:'',entries:'1',taxTreatment:'standard',...q.trade,tariff:null,fobUnit:q.trade.fobUnit??(Number(q.trade.fob)>0?String(Number(q.trade.fob)/Number(q.base.pieces)):'')};kind=q.kind;tab='quote';if(!base.destination){go(1);msg(t('请补充目的地类型后重新报价','Select a destination type to recalculate'));return}compute();go(4)})}render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_apparel_quote',description:'Populate and validate shared shipment details, then show freight type selection. Does not book or save.',inputSchema:{type:'object',properties:{product:{type:'string'},weight:{type:'number'},volume:{type:'number'},cartons:{type:'integer'},pieces:{type:'integer'},origin:{type:'string',enum:['Shanghai','Ningbo','Shenzhen','Qingdao','Xiamen']},zip:{type:'string'},destination:{type:'string',enum:['fba','awd','commercial','other']},ready:{type:'string'},deadline:{type:'string'}},required:['product','weight','volume','cartons','pieces','origin','zip','destination','ready'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const next={...input,deadline:input.deadline||''};E.valid(next);base=next;tab='quote';go(2);return{step:'choose_freight_type',demo:true}}})).catch(()=>{})}catch{}}
